/*
 * Construction Cloud user guide, published as web pages under
 * /software/construction-cloud/guide/.
 *
 * guide.json and chapters/*.html are GENERATED by scripts/gen-cc-guide.py from
 * the guide source (chapters/*.md and shots/). Edit the source and re-run the
 * script; do not edit the generated files by hand.
 */
import guide from './guide.json';

export interface CcgSection { id: string; title: string }
export interface CcgChapter {
  key: string;
  num: number;
  slug: string;
  title: string;
  part: number;
  description: string;
  sections: CcgSection[];
  figures: number;
}
export interface CcgPart { index: number; label: string; title: string; blurb: string }
export interface CcgPdf { url: string; title: string; covers: string[]; pages: number; mb: number }

export const GUIDE_PATH = '/software/construction-cloud/guide/';
export const CCG_PARTS: CcgPart[] = guide.parts;
export const CCG_CHAPTERS: CcgChapter[] = guide.chapters;
export const CCG_PDF: CcgPdf[] = guide.pdf as CcgPdf[];

const html = import.meta.glob('./chapters/*.html', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;

export const chapterHtml = (slug: string): string => html[`./chapters/${slug}.html`] ?? '';
export const chapterUrl = (c: { slug: string }) => `${GUIDE_PATH}${c.slug}/`;
export const chaptersOfPart = (part: number) => CCG_CHAPTERS.filter(c => c.part === part);
export const chapterByKey = (key: string) => CCG_CHAPTERS.find(c => c.key === key);

/* Guide chapters to read for each feature page, by source file key (stable
   across title changes). Shown on the feature pages and the product page. */
export const FEATURE_CHAPTERS: Record<string, string[]> = {
  'estimating-and-tenders': ['14_estimator', '31_ref_sales_tenders', '32_ref_estimating', '66_flow_estimate_to_award', '50_flow_tender_to_contract'],
  'boq-measurement-and-billing': ['13_commercial_qs', '41_ref_commercial_billing', '54_flow_measure_to_cash', '53_flow_subcontracts', '63_flow_month_end'],
  'contracts-notices-and-claims': ['33_ref_contracts_setup', '51_flow_contract_setup', '55_flow_variations_delays_claims', '62_flow_bonds_insurance'],
  'site-app-and-diary': ['12_site_engineer_foreman', '37_ref_site', '56_flow_site_day', '60_flow_labour_cost'],
  'quality-and-documents': ['38_ref_quality_safety', '40_ref_documents', '57_flow_quality', '58_flow_documents', '64_flow_closeout'],
  'hse': ['17_qhse', '39_ref_hse_plus', '59_flow_safety', '68_flow_hse_management'],
  'dashboards-and-reports': ['10_director', '45_ref_dashboards_reports', '46_ref_management_reports', '70_how_everything_connects'],
  'access-control-and-approvals': ['02_key_ideas', '80_expert_setup', '47_ref_configuration', '65_flow_expenses_approvals', '20_auditor'],
};

export const featureChapters = (featureSlug: string): CcgChapter[] =>
  (FEATURE_CHAPTERS[featureSlug] ?? []).map(chapterByKey).filter((c): c is CcgChapter => Boolean(c));
